DROP TABLE IF EXISTS rc_a;
DROP TABLE IF EXISTS rc_b;
CREATE TABLE rc_a (id integer, v integer);
CREATE TABLE rc_b (id integer, v integer);
INSERT INTO rc_a VALUES (1, 10), (2, 20), (3, 30);
INSERT INTO rc_b VALUES (2, 20), (3, 35), (4, 40);
SELECT COALESCE(a.id, b.id) AS id,
       CASE WHEN b.id IS NULL THEN 'missing' WHEN a.id IS NULL THEN 'extra' ELSE 'changed' END AS problem
FROM rc_a a FULL OUTER JOIN rc_b b ON b.id = a.id
WHERE a.id IS NULL OR b.id IS NULL OR a.v IS DISTINCT FROM b.v
ORDER BY 1;
